function starwayDecodeStored(value){return typeof value==='string'&&value.startsWith(STARWAY_STORAGE_PREFIX)?JSON.stringify(starwayUnpackValue(JSON.parse(value.slice(STARWAY_STORAGE_PREFIX.length)))):value;}
