function syncPauseControl(){const paused=state==='pause'||(['falling','exploding'].includes(state)&&fxPaused);pauseControl.textContent=paused?'▶':'Ⅱ';pauseControl.setAttribute('data-paused',String(paused));pauseControl.setAttribute('aria-label',paused?'항해 재개':'일시정지');pauseControl.setAttribute('aria-pressed',String(paused));}
const pauseWithControl=pause;pause=function(){pauseWithControl();if(state==='pause'){leverPointer=null;if(typeof resetJoystick==='function')resetJoystick()}syncPauseControl()};
pauseControl.addEventListener('pointerdown',e=>{if(e.button!==undefined&&e.button!==0)return;e.preventDefault();pause()});
