if(!['low','medium','high'].includes(settings.graphics))settings.graphics='high';
if(!['ko','en','ja','zh'].includes(settings.language))settings.language='ko';
if(!['buttons','joystick'].includes(settings.controls))settings.controls='buttons';
for(const key of ['bgmVolume','sfxVolume'])settings[key]=Number.isFinite(settings[key])?Math.max(0,Math.min(1,settings[key])):1;
settings.steeringSensitivity=Number.isFinite(settings.steeringSensitivity)?Math.max(.5,Math.min(1.5,settings.steeringSensitivity)):1;globalThis.starwaySteeringSettingsReady=true;
