function tr(source){if(settings.language==='ko')return source;const n={en:0,ja:1,zh:2}[settings.language];if(uiWords[source])return uiWords[source][n];return source;}
function translateDynamic(text){
 let s=tr(text);if(s!==text||settings.language==='ko')return s;
 const n={en:0,ja:1,zh:2}[settings.language];
 const tokens={'단계 · 중력 ':[' · Gravity ','段階 · 重力 ','层 · 重力 '],' · 착지 후 ':[' · on landing ',' · 着地後 ',' · 着陆后 '],'m · 획득 ':['m · earned ','m · 獲得 ','m · 获得 '],' · 제한 ':[' · Limit ',' · 制限 ',' · 限时 '],'코스 ':['Course ','コース ','关卡 '],' 시작 →':[' Start →',' 開始 →',' 开始 →'],'최단 ':['Best ','最短 ','最快 '],'이번 ':['This run ','今回 ','本次 '],'신기록!':['New best!','新記録！','新纪录！'],'항로 난도 ':['Course difficulty ','航路難度 ','航线难度 '],'무한 항로 · ':['Endless · ','無限航路 · ','无尽航线 · '],'보유 코인 ':['Coins ','所持コイン ','持有金币 '],'이 브라우저에 자동 저장':['Saved in this browser','このブラウザーに自動保存','自动保存在本浏览器中'],'최고 ':['Best ','最高 ','最高 '],' 클리어':[' cleared',' クリア',' 已完成'],' 코인':[' coins',' コイン',' 金币'],' · 신기록':[' · New best',' · 新記録',' · 新纪录']};
 for(const key of Object.keys(uiWords).filter(k=>k.length>=5).sort((a,b)=>b.length-a.length))s=s.split(key).join(uiWords[key][n]);
 for(const key of Object.keys(tokens).sort((a,b)=>b.length-a.length))s=s.split(key).join(tokens[key][n]);
 s=s.replace(/(\d+(?:\.\d+)?)초/g,'$1'+['s','秒','秒'][n]);
 return s;
}
const localizedText=new WeakMap();
function localizeUI(){
 if(document.documentElement)document.documentElement.lang=settings.language==='zh'?'zh-CN':settings.language;
 if(!document.createTreeWalker)return;
 for(const root of [document.getElementById('overlay'),document.getElementById('mapEditor'),document.querySelector('header'),document.querySelector('.cockpit'),$('note'),$('segment'),document.querySelector('.flight-strip')]){
  if(!root||root.classList?.contains?.('hidden'))continue;const walker=document.createTreeWalker(root,4);let node;
  while((node=walker.nextNode())){if(node.parentElement?.closest?.('[data-l10n-skip]'))continue;const current=node.nodeValue,old=localizedText.get(node);if(old&&old.translated===current&&old.language===settings.language)continue;const original=old&&old.translated===current?old.original:current;const trimmed=original.trim();const translated=trimmed?original.replace(trimmed,translateDynamic(trimmed)):original;localizedText.set(node,{original,translated,language:settings.language});if(current!==translated)node.nodeValue=translated;}
 }
}
function persistSettings(){data.settings={...settings};save();$('settingsNote').textContent=tr(storageOK?'설정은 변경 즉시 저장됩니다.':'저장 공간을 사용할 수 없습니다. 이번 실행에만 적용됩니다.');}
function applySettings(){
 globalThis.starwayPixelRatioCap={low:1,medium:1.5,high:2}[settings.graphics];resize();sound=settings.sound;
 $('sound').textContent=tr(sound?'소리 ON':'소리 OFF');
 $('analogStick').classList.toggle('hidden',settings.controls!=='joystick');
 $('left').classList.toggle('hidden',settings.controls!=='buttons');$('right').classList.toggle('hidden',settings.controls!=='buttons');
 resetJoystick();localizeUI();
}
let menuScreen='main';
const commandMenu=showMenu;
showMenu=function(tab='main'){
 if(revenueBusy)return;
 const custom=['main','modes','options','exit'].includes(tab);
 commandMenu(custom?'story':tab);menuScreen=tab;
 $('overlay').setAttribute('data-screen',tab);
 if(tab==='main'){
  $('title').textContent=tr('다음 항로를 향해.');$('eyebrow').textContent='STARWAY / FLIGHT COMMAND';$('description').textContent=tr('항로를 개척하거나, 끝없는 우주에 도전하세요.');
  $('hangarName').textContent=tr(skins[data.skin][0]);
  $('hangarProgress').textContent=({ko:'스토리',en:'Story',ja:'ストーリー',zh:'故事模式'})[settings.language]+' '+data.cleared.filter(i=>i<STORY_VISIBLE_COUNT).length+' / '+STORY_VISIBLE_COUNT+' · '+displayDistance(data.best)+'m';
  const g=$('hangarShip').getContext('2d');g.clearRect(0,0,600,340);g.save();g.translate(300,145);g.scale(3.5,3.5);renderShip(g,data.skin,0);g.restore();
 }else if(tab==='endless'){$('title').textContent=tr('무한 모드');$('eyebrow').textContent='ENDLESS RUN';const words={ko:['최고기록','매번 새로운 항로에 도전하세요.'],en:['Personal best','Challenge a new route every run.'],ja:['自己ベスト','毎回新しい航路に挑戦。'],zh:['个人最佳','每次挑战全新的航线。']}[settings.language];$('description').textContent=words[0]+' '+displayDistance(data.best)+' m · '+words[1];}
 if(tab==='modes'){$('title').textContent=tr('모드 선택');$('eyebrow').textContent='SELECT MISSION';$('description').textContent=tr('도전할 항로를 선택하세요.');}
 else if(tab==='options'){$('title').textContent=tr('옵션');$('eyebrow').textContent='FLIGHT SETTINGS';$('description').textContent='';for(const [key,id] of [['graphics','settingGraphics'],['language','settingLanguage'],['controls','settingControls']])$(id).value=settings[key];$('settingSound').value=settings.sound?'on':'off';$('settingsNote').textContent=tr(storageOK?'설정은 변경 즉시 저장됩니다.':'저장 공간을 사용할 수 없습니다. 이번 실행에만 적용됩니다.');}
 else if(tab==='exit'){$('title').textContent=tr('나가기');$('eyebrow').textContent='FLIGHT ENDED';$('description').textContent=tr('브라우저의 닫기 또는 뒤로 버튼으로 게임을 종료할 수 있습니다.');}
 else if(tab==='story'){$('title').textContent=tr('스토리 항로');$('eyebrow').textContent='SELECT COURSE';if(settings.language!=='ko'){const info={en:['Gravity','Time limit','Best'],ja:['重力','制限時間','最短'],zh:['重力','时间限制','最快']}[settings.language];$('description').textContent=STORY_COURSES[level].title+' · '+info[0]+' '+stageProfile().gravity+(data.storyTimes[level]?' · '+info[2]+' '+data.storyTimes[level].best.toFixed(2)+(settings.language==='en'?'s':'秒'):'');}}
 for(const [id,label] of [['menuPlay','시작'],['menuOptions','옵션'],['menuExit','나가기'],['story','스토리'],['endless','무한 모드'],['recordsOpen','기록 보기'],['shop','상점'],['editorOpen','맵 에디터']])$(id).textContent=tr(label);
 $('home').classList.toggle('hidden',tab==='main');
 $('home').textContent=tr(tab==='modes'||tab==='options'||tab==='exit'?'메인 메뉴':'뒤로');
 localizeUI();
};
$('menuPlay').onclick=()=>showMenu('modes');$('menuOptions').onclick=()=>showMenu('options');
$('menuExit').onclick=()=>{resetJoystick();persistSettings();showMenu('exit');if(typeof window!=='undefined'&&typeof window.close==='function')window.close();};
$('story').onclick=()=>showMenu('story');$('endless').onclick=()=>{if(revenueBusy)return;mode='endless';beginRun();localizeUI()};
$('home').onclick=()=>{if(['pause','result'].includes(menuScreen)||['pause','win','dead'].includes(state)){showMenu(mode==='endless'?'endless':'story');return;}showMenu(['story','endless','records','shop'].includes(menuScreen)?'modes':'main');};
for(const [id,key] of [['settingGraphics','graphics'],['settingSound','sound'],['settingLanguage','language'],['settingControls','controls']])$(id).onchange=()=>{settings[key]=key==='sound'?$(id).value==='on':$(id).value;if(key==='language')settings.languageConfirmed=true;applySettings();persistSettings();if(key==='language')showMenu('options');};
$('sound').onclick=()=>{settings.sound=!settings.sound;sound=settings.sound;persistSettings();$('sound').textContent=tr(sound?'소리 ON':'소리 OFF');beep(700)};
const commandFinish=finish;finish=function(win,reason){if(state==='play'){$('overlay').setAttribute('data-screen','result');menuScreen='result';}const result=commandFinish(win,reason);$('home').textContent=tr('뒤로');localizeUI();return result};
const commandPause=pause;pause=function(){if(state==='play'||state==='ready'){$('overlay').setAttribute('data-screen','pause');menuScreen='pause';}const result=commandPause();if(state==='pause')$('home').textContent=tr('뒤로');localizeUI();return result};
let stickPointer=null;
function releaseAnalog(){stickPointer=null;steeringAxis=0;$('analogKnob').style.transform='translate(-50%,-50%)';$('analogStick').setAttribute('aria-valuenow','0');$('analogStick').setAttribute('data-direction','neutral');}
const commandReset=resetJoystick;resetJoystick=function(){releaseAnalog();return commandReset()};
function moveAnalog(e){const rect=$('analogStick').getBoundingClientRect();const knob=$('analogKnob').getBoundingClientRect();const knobWidth=knob.width>0&&knob.width<rect.width?knob.width:Math.min(56,rect.width*.44);const radius=Math.max(1,(rect.width-knobWidth)/2-10);const dx=Math.max(-radius,Math.min(radius,e.clientX-(rect.left+rect.width/2)));const axis=dx/radius;steeringAxis=Math.abs(axis)<.12?0:Math.sign(axis)*(Math.abs(axis)-.12)/.88;$('analogKnob').style.transform='translate(calc(-50% + '+dx+'px),-50%)';$('analogStick').setAttribute('aria-valuenow',String(Math.round(steeringAxis*100)));$('analogStick').setAttribute('data-direction',steeringAxis<0?'left':steeringAxis>0?'right':'neutral');}
$('analogStick').addEventListener('pointerdown',e=>{if(settings.controls!=='joystick'||!['ready','play'].includes(state)||stickPointer!==null||(e.button!==undefined&&e.button!==0))return;e.preventDefault();stickPointer=e.pointerId;$('analogStick').setPointerCapture(e.pointerId);moveAnalog(e)});
$('analogStick').addEventListener('pointermove',e=>{if(e.pointerId===stickPointer){e.preventDefault();moveAnalog(e)}});
for(const name of ['pointerup','pointercancel','lostpointercapture'])$('analogStick').addEventListener(name,e=>{if(e.pointerId===stickPointer){e.preventDefault();releaseAnalog()}});
for(const name of ['contextmenu','selectstart','dragstart'])$('analogStick').addEventListener(name,e=>e.preventDefault());
$('analogStick').addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();steeringAxis=e.key==='ArrowLeft'?-1:1;}});
$('analogStick').addEventListener('keyup',releaseAnalog);$('analogStick').addEventListener('blur',releaseAnalog);
if(typeof MutationObserver!=='undefined'){let localizing=false;const observer=new MutationObserver(()=>{if(localizing)return;localizing=true;localizeUI();observer.takeRecords();localizing=false});observer.observe(document.body,{subtree:true,childList:true,characterData:true});}

