function renderReleaseHangar(){
 const g=$('hangarShip').getContext('2d');g.clearRect(0,0,600,340);
 const bg=g.createRadialGradient(310,145,10,310,145,340);bg.addColorStop(0,'#193e58');bg.addColorStop(.55,'#0b1b2e');bg.addColorStop(1,'#07111c');g.fillStyle=bg;g.fillRect(0,0,600,340);
 for(let i=0;i<72;i++){g.fillStyle=i%5?'#8db2c877':'#ebf8ff';g.fillRect((Math.sin(i*97.7)*.5+.5)*600,(Math.cos(i*53.3)*.5+.5)*300,i%7?1:2,1)}
 // A runway leading into the light gives the ship scale without a UI frame.
 g.beginPath();g.moveTo(70,340);g.lineTo(283,75);g.lineTo(317,75);g.lineTo(530,340);g.closePath();g.fillStyle='#142e43';g.fill();
 g.strokeStyle='#63d6ee55';g.lineWidth=1;for(const side of [-1,1]){g.beginPath();g.moveTo(300+side*230,340);g.lineTo(300+side*17,75);g.stroke()}
 for(let i=0;i<8;i++){const yy=110+i*i*4;g.fillStyle='#7ce1ec';g.fillRect(298,yy,4,4+i)}
 g.save();g.translate(300,201);renderFlightShip(g,data.skin,0,140,{foreshortening:.7,shear:0});g.restore();
}
function renderReleaseCourse(){
 const c=STORY_COURSES[level],g=$('hangarShip').getContext('2d');g.clearRect(0,0,600,340);g.fillStyle='#091522';g.fillRect(0,0,600,340);
 const end=Math.min(c.tiles.length,100),w=50,step=2.8,left=125;
 for(let r=0;r<end;r++)for(let l=0;l<7;l++){const tile=c.tiles[r][l];if(!tile)continue;const color=c.roadPaint?.[r]?.[l]||'gray';g.fillStyle=ROAD_PAINT_COLORS[color]||'#7c9aaa';g.globalAlpha=tile===2||tile===8?1:.65;g.fillRect(left+l*w,310-r*step,w-2,step+.3);if(tile===2||tile===8){g.fillStyle='#eff9ff77';g.fillRect(left+l*w,310-r*step,w-2,1)}if(c.ceilings?.[r]&&(c.tunnelCenters?.[r]||[]).some(x=>Math.abs(x-(l-3))<.1)){g.fillStyle='#e7f5f9';g.fillRect(left+l*w+4,310-r*step,w-10,1)}}
 g.globalAlpha=1;g.fillStyle='#82e9ee';g.beginPath();g.moveTo(300,318);g.lineTo(292,331);g.lineTo(308,331);g.closePath();g.fill();
}
const releaseMenu=showMenu;
