// Change steering without leaving a paused run; share the Options preference.
function syncPauseControls(){
 $('pauseControlsLabel').textContent=tr('조작설정');
 for(const [id,value,label] of [['pauseUseButtons','buttons','좌우 버튼'],['pauseUseJoystick','joystick','아날로그 조이스틱']]){
  const active=settings.controls===value;$(id).textContent=tr(label);$(id).setAttribute('aria-pressed',String(active));$(id).classList.toggle('selected',active);
 }
}
function setPausedControls(value){
 if(state!=='pause')return;
 clearTouchControls();resetJoystick();settings.controls=value;$('settingControls').value=value;applySettings();persistSettings();syncPauseControls();
}
$('pauseUseButtons').onclick=()=>setPausedControls('buttons');
$('pauseUseJoystick').onclick=()=>setPausedControls('joystick');
