function challengeStarTotal(game=data){return ['sprint','reserve','precision'].reduce((sum,id)=>sum+(Number.isInteger(game.challenges?.[id]?.stars)?Math.max(0,Math.min(3,game.challenges[id].stars)):0),0);}
