 for(let i=0;i<6;i++)for(let j=0;j<2;j++)releaseGroundQuad(a+i/6+.006,a+(i+1)/6-.006,r+.36+j*.14,r+.49+j*.14,.019,(i+j)%2?'#fff2b4':'#a5751c');
