 ctx.globalAlpha=alpha*.18;ctx.strokeStyle='#ffe7a1';for(let n=-2;n<=2;n++){ctx.beginPath();ctx.moveTo(-size*2,n*size*.22);ctx.lineTo(size*2,n*size*.22);ctx.stroke()}
